B.Me=new A.fa("Git & GitHub","Version control",B.CC,B.AV,"Every project is versioned on GitHub with Conventional Commits (feat, fix, build, docs, chore). Secrets stay out of the repo: API keys are injected at build time with --dart-define. This resume is itself deployed on GitHub Pages.",B.Dx)
B.Cv=new A.dk(62870,"MaterialIcons",!1)
